$paths = @(
  "$env:USERPROFILE\.kilo\logs",
  "$env:USERPROFILE\.config\kilo\logs",
  "$env:APPDATA\kilo",
  "$env:LOCALAPPDATA\kilo",
  "$env:USERPROFILE\.config\kilo",
  "$env:USERPROFILE\.kilo"
)
foreach ($p in $paths) {
  if (Test-Path -LiteralPath $p) {
    Write-Host "=== $p ==="
    Get-ChildItem -LiteralPath $p -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 15 Name, LastWriteTime, Length | Format-Table -AutoSize
  }
}

$candidates = @(
  "$env:APPDATA\Code\logs",
  "$env:APPDATA\Kilo",
  "$env:LOCALAPPDATA\kilo",
  "$env:USERPROFILE\.kilo",
  "$env:APPDATA\OpenCode",
  "$env:USERPROFILE\.local\share\opencode",
  "$env:USERPROFILE\.config\opencode"
)
foreach ($p in $candidates) {
  if (Test-Path -LiteralPath $p) {
    Write-Host "FOUND $p"
    Get-ChildItem -LiteralPath $p -Recurse -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 8 FullName, LastWriteTime, Length
  } else {
    Write-Host "MISS $p"
  }
}

